<include file="Public:header"/>	<div class="mainbox">		<div id="nav" class="mainnav_title">			<ul>				<a href="{pigcms{:U('Wxapp/wxapp_list')}">打开其他小程序列表</a>|				<a href="{pigcms{:U('Wxapp/web_list')}" class="on">打开其他网页列表</a>			</ul>		</div>				<div class="page_tips">			<button  onclick="window.top.artiframe('{pigcms{:U('Wxapp/web_edit')}','添加网页',600,420,true,false,false,addbtn,'add',true);" class="button" style="margin-right: 14px;">添加网页</button>			说明： 请对应小程序后台的业务域名进行填写，需要与小程序后台的业务域名保持一致填写，最多支持填写20个域名，填写时无需http://。		</div>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>编号</th>							<th>名称</th>							<th>域名</th>							<th>添加时间</th>							<th class="textcenter">操作</th>						</tr>					</thead>					<tbody>						<if condition="is_array($wxapp_list)">							<volist name="wxapp_list" id="vo">								<tr>									<td>{pigcms{$vo.pigcms_id}</td>									<td>{pigcms{$vo.name}</td>									<td>{pigcms{$vo.domain}</td>									<td>{pigcms{$vo.time|date='Y-m-d H:i:s',###}</td>									<td class="textcenter"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Wxapp/web_edit',array('id'=>$vo['pigcms_id']))}','编辑小程序信息',600,420,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.pigcms_id}" url="{pigcms{:U('Wxapp/web_del')}">删除</a></td>								</tr>							</volist>						<else/>							<tr><td class="textcenter red" colspan="8">列表为空！</td></tr>						</if>					</tbody>				</table>			</div>		</form>	</div><include file="Public:footer"/>